import {analyzeFrame,DEFAULT_OPTIONS} from './vision.mjs';
import {classifyCase,summarizeCases} from './metrics.mjs';
import {captureVideoFrames} from './media-evaluation.mjs';
import {analyzeLocalPair,localRegistrationIdentity} from './local-registration.mjs';

const $=id=>document.getElementById(id);
const canvas=$('evaluation-canvas'),ctx=canvas.getContext('2d'),overlay=$('evaluation-overlay'),pen=overlay.getContext('2d'),video=$('evaluation-video');
const defaultRegion=[{x:.36,y:.43},{x:.64,y:.43},{x:.84,y:.96},{x:.16,y:.96}];
let cases=[],selected=null,busy=false,controller=null,drawing=false,draft=[],view='reference',engineSha=null,engineIdentity=null,engineError=null,frozen=null,toastTimer=null,history=[],reportUrl=null;
const analysisWidth=240;
const phaseNames={reference:'空置参考',occupied:'区域内占用',cleared:'移走后'};
const splitNames={development:'开发',unseen:'未见（用户声明）',regression:'回归',synthetic:'合成'};
const resultNames={obstructed:'提示疑似障碍',clear:'未见新增变化',uncertain:'不可判'};
function active(){return cases.find(c=>c.id===selected);}
function notify(message){$('evaluation-toast').textContent=message;$('evaluation-toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('evaluation-toast').hidden=true,6000);}
function textNode(tag,text,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;return el;}
async function fingerprint(pin=false){const files=['vision.mjs','local-registration.mjs'];const sources=await Promise.all(files.map(async file=>{const response=await fetch('./'+file,{cache:'no-store'});if(!response.ok)throw new Error('无法读取视觉引擎版本。');return file+'\n'+await response.text();}));const identity=await localRegistrationIdentity();if(pin)engineIdentity=structuredClone(identity);const bytes=new TextEncoder().encode(sources.join('\n')+'\n'+JSON.stringify(identity));const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(n=>n.toString(16).padStart(2,'0')).join('');}
function showEngine(){const status=frozen?`冻结于 ${new Date(frozen.at).toLocaleString('zh-CN',{hour12:false})}`:'尚未冻结（可做开发验证）';$('engine-identity').textContent=engineError||`引擎 SHA-256 ${engineSha?.slice(0,16)||'…'} · 分析宽 ${analysisWidth}px · ${status}`;$('freeze-engine').disabled=busy||!engineSha;}
fingerprint(true).then(hash=>{engineSha=hash;showEngine();}).catch(error=>{engineError=error.message;showEngine();});
function metadata(){return {source:$('evaluation-split').value==='synthetic'?'synthetic':$('self-recorded').checked?'self_recorded':'unverified',split:$('evaluation-split').value,independentDeclared:$('self-recorded').checked,afterFreezeDeclared:$('after-freeze').checked,frozenAt:frozen?.at||null};}
function syncControls(){const c=active(),locked=!!c?.firstRun;$('evaluation-files').disabled=busy;$('evaluation-split').disabled=busy;$('self-recorded').disabled=busy;$('after-freeze').disabled=busy;for(const id of ['group-id','time-reference','time-occupied','time-cleared'])$(id).disabled=!c||busy||locked;for(const id of ['prepare-case','evaluation-draw','evaluation-preset','apply-coordinates'])$(id).disabled=!c||busy||locked;$('truth-reviewed').disabled=!c?.frames||busy||locked;$('run-one').disabled=!c?.reviewed||busy||!engineSha;$('run-all').disabled=busy||!cases.some(item=>item.reviewed)||!engineSha;$('export-evaluation').disabled=!history.length||busy;$('freeze-engine').disabled=busy||!engineSha;$('run-one').textContent=locked?'再次运行（首次成绩保留）':'评测当前场景';$('cancel-run').hidden=!busy;document.querySelector('.evaluation-workspace').setAttribute('aria-busy',String(busy));for(const button of document.querySelectorAll('.case-button'))button.disabled=busy;for(const input of document.querySelectorAll('#coordinate-fields input'))input.disabled=!c||busy||locked;}
function showError(message){$('case-error').textContent=message||'';$('case-error').hidden=!message;$('case-status').classList.toggle('error',!!message);if(message)$('case-status').textContent='需检查';}
function renderLibrary(){$('case-count').textContent=`${cases.length} 组`;$('case-empty').hidden=cases.length>0;$('case-list').replaceChildren();for(const c of cases){const button=textNode('button','',`case-button${c.id===selected?' selected':''}`);button.type='button';button.disabled=busy;button.setAttribute('aria-pressed',String(c.id===selected));button.append(textNode('strong',c.label),textNode('span',c.file.name),textNode('span',c.firstRun?`已有首次结果 · ${c.attempts.length} 次运行`:c.error?'输入有问题':c.reviewed?'真值已确认':c.frames?'待确认真值':'待读取'));button.addEventListener('click',()=>selectCase(c.id));$('case-list').append(button);}}
function setCoords(){const c=active();$('coordinate-fields').replaceChildren();for(let i=0;i<4;i++){const field=document.createElement('fieldset');field.append(textNode('legend',`角 ${i+1}`));for(const axis of ['x','y']){const label=textNode('label',axis.toUpperCase());const input=document.createElement('input');input.type='number';input.min=0;input.max=1;input.step=.01;input.value=c?.polygon[i][axis]??defaultRegion[i][axis];input.id=`point-${i}-${axis}`;input.setAttribute('aria-label',`角${i+1} ${axis.toUpperCase()} 归一化坐标`);label.htmlFor=input.id;label.append(input);field.append(label);}$('coordinate-fields').append(field);}}
function drawRegion(){pen.clearRect(0,0,overlay.width,overlay.height);const c=active();if(!c)return;const result=c.firstRun?.rows.find(row=>row.phase===view)?.analysis;const pts=drawing?draft:result?.displayPolygon||c.polygon;if(pts.length){pen.beginPath();pts.forEach((p,i)=>i?pen.lineTo(p.x*overlay.width,p.y*overlay.height):pen.moveTo(p.x*overlay.width,p.y*overlay.height));if(pts.length>2){pen.closePath();pen.fillStyle='#61aa7928';pen.fill();}pen.strokeStyle='#b3e2c2';pen.lineWidth=3;pen.setLineDash([10,8]);pen.stroke();pen.setLineDash([]);for(const p of pts){pen.beginPath();pen.arc(p.x*overlay.width,p.y*overlay.height,6,0,Math.PI*2);pen.fillStyle='#ecfff1';pen.fill();}}
  if(!drawing&&result?.status==='obstructed'&&result.boxes)for(const box of result.boxes){pen.strokeStyle='#ffbe72';pen.lineWidth=3;pen.strokeRect(box.x*overlay.width,box.y*overlay.height,box.width*overlay.width,box.height*overlay.height);}
}
function paint(){const c=active(),img=c?.images?.[view];const w=960,h=img?Math.round(w*img.naturalHeight/img.naturalWidth):600;canvas.width=overlay.width=w;canvas.height=overlay.height=h;const stage=document.querySelector('.eval-stage');stage.style.aspectRatio=`${w}/${h}`;stage.classList.toggle('portrait',h>w);ctx.fillStyle='#26372e';ctx.fillRect(0,0,w,h);if(img)ctx.drawImage(img,0,0,w,h);else{ctx.fillStyle='#e4eee3';ctx.font='22px sans-serif';ctx.textAlign='center';ctx.fillText(c?'点击“读取三个时刻”查看素材':'等待实拍素材',w/2,h/2);}$('preview-label').textContent=c?`${c.label} · ${phaseNames[view]}${c.frames?` · ${c.mediaTimes[view].toFixed(2)}s`:''}`:'等待实拍素材';drawRegion();}
function renderPreviews(){const c=active();$('frame-previews').replaceChildren();$('frame-previews').hidden=!c?.frames;if(!c?.frames)return;for(const phase of Object.keys(phaseNames)){const button=textNode('button','',`frame-preview${view===phase?' selected':''}`);button.type='button';button.setAttribute('aria-pressed',String(view===phase));const img=document.createElement('img');img.src=c.previews[phase];img.alt=`${c.label} ${phaseNames[phase]}，供人工核对`;button.append(img,textNode('span',`${phaseNames[phase]} · ${c.mediaTimes[phase].toFixed(2)}s`));button.addEventListener('click',()=>{if(busy)return;view=phase;renderPreviews();paint();});$('frame-previews').append(button);}}
function selectCase(id){if(busy)return;selected=id;drawing=false;draft=[];view='reference';const c=active();$('group-id').value=c.label;for(const phase of ['reference','occupied','cleared'])$(`time-${phase}`).value=c.times[phase];$('truth-reviewed').checked=c.reviewed;$('editor-title').textContent=c.label;$('editor-caption').textContent=c.duration?`${c.file.name} · ${c.duration.toFixed(2)}s · ${c.originalSize.width}×${c.originalSize.height}`:c.file.name;$('case-status').textContent=c.firstRun?'首次结果已锁定':c.reviewed?'真值已确认':c.frames?'待人工确认':'待读取';$('evaluation-draw').textContent='点选四角';showError(c.error);setCoords();renderLibrary();renderPreviews();paint();syncControls();}
function invalidate(c){c.frames=null;c.previews=null;c.images=null;c.reviewed=false;c.error=null;$('truth-reviewed').checked=false;renderPreviews();paint();syncControls();}
$('evaluation-files').addEventListener('change',event=>{const files=[...event.target.files];event.target.value='';for(const file of files){if(cases.length>=20){notify('本次会话最多 20 组，先完成并导出这一批。');break;}if(!file.type.startsWith('video/')&&!/\.(mov|mp4|m4v|webm)$/i.test(file.name)){notify(`${file.name} 不是支持的视频类型。`);continue;}const duplicate=cases.find(c=>c.file.name===file.name&&c.file.size===file.size&&c.file.lastModified===file.lastModified);if(duplicate){notify(`${file.name} 已登记，重复导入不增加场景数。`);continue;}cases.push({id:crypto.randomUUID(),registeredAt:new Date().toISOString(),label:`DEV${String(cases.length+1).padStart(2,'0')}`,file,times:{reference:2,occupied:12,cleared:19},polygon:structuredClone(defaultRegion),reviewed:false,frames:null,images:null,error:null,firstRun:null,attempts:[]});}renderLibrary();if(!selected&&cases.length)selectCase(cases[0].id);syncControls();renderResults();});
function updateGroupId(){const c=active(),next=$('group-id').value.trim();if(!c||c.firstRun)return;if(!next||cases.some(other=>other.id!==c.id&&other.label===next)){notify('场景编号需非空且不能重复。');$('group-id').value=c.label;return;}c.label=next;renderLibrary();renderResults();$('editor-title').textContent=next;paint();}
$('group-id').addEventListener('change',updateGroupId);
$('group-id').addEventListener('blur',updateGroupId);
for(const phase of ['reference','occupied','cleared'])$(`time-${phase}`).addEventListener('input',()=>{const c=active();if(!c||c.firstRun)return;c.times[phase]=Number($(`time-${phase}`).value);invalidate(c);notify('取帧时刻已改变，请重新读取并确认真值。');});
function checkCancelled(signal){if(signal?.aborted)throw new DOMException('已停止评测。','AbortError');}
async function decodeImages(previews,signal){const images={};await Promise.all(Object.entries(previews).map(([key,src])=>new Promise((resolve,reject)=>{const image=new Image();let timer;const cleanup=()=>{clearTimeout(timer);signal?.removeEventListener('abort',cancel);image.onload=image.onerror=null;};const fail=error=>{cleanup();reject(error);};const cancel=()=>fail(new DOMException('已停止评测。','AbortError'));image.onload=()=>{cleanup();images[key]=image;resolve();};image.onerror=()=>fail(new Error('帧预览无法解码。'));signal?.addEventListener('abort',cancel,{once:true});timer=setTimeout(()=>fail(new Error('帧预览解码超时。')),10000);if(signal?.aborted){cancel();return;}image.src=src;})));checkCancelled(signal);return images;}
async function prepare(c,signal){c.error=null;c.frames=null;c.previews=null;c.images=null;c.reviewed=false;const data=await captureVideoFrames(c.file,c.times,video,{signal,analysisWidth,onProgress:progress=>{$('run-status').textContent=`${c.label} · ${({loading:'读取视频',seeking:'定位画面',capturing:'提取画面',hashing:'核对文件',complete:'准备完成'})[progress.stage]||progress.stage} ${progress.completed??0}/3`;}});if(metadata().split==='unseen'&&cases.some(other=>other.id!==c.id&&other.fileSha256===data.fileSha256))throw new Error('该视频内容与已登记文件重复，不能作为独立未见场景。');const images=await decodeImages(data.previews,signal);checkCancelled(signal);Object.assign(c,data,{images,preparedAt:new Date().toISOString()});if(metadata().split!=='unseen')c.developmentUsed=true;return c;}
$('prepare-case').addEventListener('click',async()=>{const c=active();if(!c||busy)return;busy=true;controller=new AbortController();syncControls();try{await prepare(c,controller.signal);c.reviewed=false;}catch(error){c.error=error.message;c.reviewed=false;}finally{busy=false;controller=null;selectCase(c.id);$('run-status').textContent=c.error?'素材读取失败，原登记仍保留。':'三个时刻已读取，请先核对真值和区域。';}});
$('truth-reviewed').addEventListener('change',()=>{const c=active();if(!c||c.firstRun)return;c.reviewed=$('truth-reviewed').checked;$('case-status').textContent=c.reviewed?'真值已确认':'待人工确认';renderLibrary();syncControls();});
function changeRegion(points){const c=active();if(!c||c.firstRun)return;c.polygon=structuredClone(points);c.reviewed=false;$('truth-reviewed').checked=false;drawing=false;draft=[];$('evaluation-draw').textContent='点选四角';setCoords();drawRegion();syncControls();notify('区域已更新，请重新核对人工真值。');}
$('evaluation-draw').addEventListener('click',()=>{const c=active();if(!c||c.firstRun)return;drawing=!drawing;draft=[];view='reference';$('evaluation-draw').textContent=drawing?'取消标定':'点选四角';$('region-help').textContent=drawing?'沿区域边缘点选四角；键盘用户可使用下方数值坐标。':'在参考帧中标定空置区域，后两个时刻使用同一区域。';renderPreviews();paint();});
overlay.addEventListener('click',event=>{if(!drawing||busy)return;const rect=overlay.getBoundingClientRect();draft.push({x:Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height))});if(draft.length===4)changeRegion(draft);else drawRegion();});
overlay.addEventListener('keydown',event=>{if(event.key==='Escape'){drawing=false;draft=[];$('evaluation-draw').textContent='点选四角';drawRegion();}});
$('evaluation-preset').addEventListener('click',()=>changeRegion(defaultRegion));
$('apply-coordinates').addEventListener('click',()=>{const points=Array.from({length:4},(_,i)=>({x:Number($(`point-${i}-x`).value),y:Number($(`point-${i}-y`).value)}));if(points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>1||p.y<0||p.y>1)){notify('坐标须为 0 到 1 的数值。');return;}changeRegion(points);});
$('freeze-engine').addEventListener('click',()=>{if(!engineSha)return;frozen={at:new Date().toISOString(),sha256:engineSha,backendIdentity:engineIdentity,options:structuredClone(DEFAULT_OPTIONS),analysisWidth};$('after-freeze').checked=false;showEngine();notify('当前版本已冻结。未见测试素材应从此后开始拍摄。');});
function evidence(c,phase,result){const img=c.images?.[phase];if(!img)return null;const out=document.createElement('canvas');out.width=640;out.height=Math.round(640*img.naturalHeight/img.naturalWidth);const p=out.getContext('2d');p.drawImage(img,0,0,out.width,out.height);p.beginPath();(result?.displayPolygon||c.polygon).forEach((point,i)=>i?p.lineTo(point.x*out.width,point.y*out.height):p.moveTo(point.x*out.width,point.y*out.height));p.closePath();p.strokeStyle='#388c60';p.lineWidth=3;p.stroke();for(const b of result?.status==='obstructed'?result.boxes||[]:[]){p.strokeStyle='#c07520';p.lineWidth=3;p.strokeRect(b.x*out.width,b.y*out.height,b.width*out.width,b.height*out.height);}return out.toDataURL('image/jpeg',.8);}
function row(c,phase,meta,analysis,elapsedMs=null){return {groupId:c.label,phase,truth:phase==='occupied'?'occupied':'clear',status:analysis?.status||'uncertain',elapsedMs,source:meta.source,split:meta.split,independentDeclared:meta.independentDeclared&&(!meta.split.startsWith('unseen')||meta.afterFreezeDeclared),analysis:analysis||{status:'uncertain',reason:'not_evaluated',message:'尚未运行或尚未确认人工真值。'},mediaTime:c.mediaTimes?.[phase]??c.times[phase],evidence:analysis?evidence(c,phase,analysis):null};}
function plannedRows(){return cases.flatMap(c=>c.firstRun?.rows||['occupied','cleared'].map(phase=>row(c,phase,metadata(),null)));}
function summary(){const rows=plannedRows(),s=summarizeCases(rows);s.pendingGroups=cases.filter(c=>!c.firstRun).length;s.failedGroups=cases.filter(c=>c.firstRun?.error).length;s.numericGateMet=s.numericGateMet&&s.pendingGroups===0&&s.failedGroups===0;s.evidenceStatus='self_declared_unverified';return s;}
const percent=value=>value===null?'N/A':`${(value*100).toFixed(1)}%`;
function renderResults(){const hasRuns=history.length>0;$('export-evaluation').disabled=!hasRuns||busy;let s;try{s=summary();}catch(error){showError(error.message);return;}for(const [id,value] of [['occupancy-rate',s.occupancyAlertRate],['clear-rate',s.clearConfirmationRate],['coverage-rate',s.coverage]])$(id).textContent=hasRuns?percent(value):'—';$('median-time').textContent=hasRuns&&s.medianMs!==null?`${s.medianMs.toFixed(1)} ms`:'—';$('gate-status').textContent=!hasRuns?'至少 10 组独立未见场景的实拍门槛尚未验证。':s.numericGateMet?'数字条件已达到（基于用户声明）。素材真实性、独立性和完整实拍闭环仍需审核。':`当前 ${cases.filter(c=>c.firstRun).length}/${cases.length} 组有首次记录；占用 TP ${s.counts.TP}/${s.positiveTotal}，移走后 TN ${s.counts.TN}/${s.negativeTotal}，不可判/未完成 ${s.counts.UP+s.counts.UN}。实拍门槛尚未验证。`;$('results-body').replaceChildren();if(!cases.length){const tr=document.createElement('tr'),td=textNode('td','等待实拍数据。');td.colSpan=4;tr.append(td);$('results-body').append(tr);}for(const c of cases){const tr=document.createElement('tr'),name=textNode('td',c.label);name.append(textNode('small',c.firstRun?splitNames[c.firstRun.metadata.split]:'用途尚未锁定'));tr.append(name);for(const phase of ['occupied','cleared']){const r=c.firstRun?.rows.find(item=>item.phase===phase),td=document.createElement('td');if(r){td.append(textNode('span',`${classifyCase(r.truth,r.status)} · ${resultNames[r.status]}`,`result-tag${r.status==='uncertain'||['FN','FP'].includes(classifyCase(r.truth,r.status))?' warning':''}`),textNode('small',r.analysis.message||r.analysis.reason));}else td.textContent='未评测';tr.append(td);}const note=textNode('td',c.firstRun?.error?'输入/处理失败，计入分母':c.firstRun?'首次成绩保留':c.error||'等待真值确认与评测');note.append(textNode('small',c.firstRun?`${c.attempts.length} 次运行`:'未完成组不会计作正确'));tr.append(note);$('results-body').append(tr);}}
async function run(list){if(busy||!list.length)return;if(!engineSha||engineError){notify('请先确认视觉引擎版本可读取。');return;}const meta=metadata();if(meta.split==='unseen'&&(!frozen||!meta.afterFreezeDeclared)){notify('未见测试需要先冻结版本，并声明素材是在冻结后拍摄且未用于调参。');return;}busy=true;controller=new AbortController();syncControls();try{if(await fingerprint()!==engineSha)throw new Error('视觉源码已发生变化，请导出已有记录后刷新，不能混合版本评分。');for(const c of list){await new Promise(resolve=>setTimeout(resolve,0));if(controller.signal.aborted)break;const runId=crypto.randomUUID(),time=new Date().toISOString();let rows,error=null;try{if(!c.reviewed)throw new Error('未确认人工真值，不能运行此场景。');if(meta.split==='unseen'&&(!c.registeredAt||Date.parse(c.registeredAt)<=Date.parse(frozen.at)||c.developmentUsed))throw new Error('该素材在冻结前已登记或曾用于开发/回归，不能作为本轮未见素材。请先导出本会话，再刷新并冻结版本，随后拍摄并导入未见素材。');if(!c.frames)await prepare(c,controller.signal);if(meta.split==='unseen'&&cases.some(other=>other.id!==c.id&&other.fileSha256===c.fileSha256))throw new Error('该视频内容与已登记文件重复，不能作为独立未见场景。');if(drawing&&selected===c.id)throw new Error('请先完成区域标定。');rows=[];for(const phase of ['occupied','cleared']){const started=performance.now(),result=await analyzeLocalPair(c.frames.reference,c.frames[phase],c.polygon,{referencePreview:c.previews.reference,currentPreview:c.previews[phase],signal:controller.signal,options:DEFAULT_OPTIONS,expectedIdentity:engineIdentity});rows.push(row(c,phase,meta,result,performance.now()-started));}}catch(failure){error=failure.message;rows=['occupied','cleared'].map(phase=>row(c,phase,meta,{status:'uncertain',reason:failure.name==='AbortError'?'cancelled':'input_error',message:error,overlapRatio:0,boxes:[]}));}const record={runId,time,groupId:c.label,fileName:c.file.name,fileSha256:c.fileSha256||null,metadata:{...meta},engine:{sha256:engineSha,backendIdentity:engineIdentity,options:structuredClone(DEFAULT_OPTIONS),analysisWidth,frozenAt:frozen?.at||null},times:structuredClone(c.times),actualMediaTimes:c.mediaTimes?{...c.mediaTimes}:null,polygon:structuredClone(c.polygon),truthReviewed:c.reviewed,rows,error};c.attempts.push(record);history.push(record);if(!c.firstRun)c.firstRun=record;c.error=error;$('run-status').textContent=`已记录 ${c.label}：${error?'输入失败，已保留':rows.map(r=>classifyCase(r.truth,r.status)).join(' / ')}。`;renderLibrary();renderResults();if(c.id===selected){paint();showError(c.error);if(!c.error)$('case-status').textContent='首次结果已锁定';}}}catch(error){notify(error.message);$('run-status').textContent=error.message;}finally{busy=false;controller=null;renderLibrary();syncControls();renderResults();}}
$('run-one').addEventListener('click',()=>run([active()].filter(Boolean)));$('run-all').addEventListener('click',()=>run(cases.filter(c=>c.reviewed)));
$('export-evaluation').addEventListener('click',()=>{if(!history.length)return;const report={project:'ClearPath',schemaVersion:1,exportedAt:new Date().toISOString(),evidenceStatus:'self_declared_unverified',scope:'reference-frame comparison; not safety certification or end-to-end latency',summary:summary(),engineSha256:engineSha,backendIdentity:engineIdentity,engineComponents:['vision.mjs','local-registration.mjs','local backend identity when available'],options:structuredClone(DEFAULT_OPTIONS),analysisWidth,frozen,plannedCases:cases.map(c=>({groupId:c.label,registeredAt:c.registeredAt,preparedAt:c.preparedAt||null,developmentUsed:!!c.developmentUsed,fileName:c.file.name,fileSize:c.file.size,fileLastModified:c.file.lastModified,fileSha256:c.fileSha256||null,duration:c.duration||null,originalSize:c.originalSize||null,times:c.times,polygon:c.polygon,truthReviewed:c.reviewed,firstRunId:c.firstRun?.runId||null,error:c.error||null,pending:!c.firstRun})),firstResults:cases.flatMap(c=>c.firstRun?.rows||['occupied','cleared'].map(phase=>row(c,phase,metadata(),null))),allAttempts:history,notes:['缺失、不可判和处理失败不计正确；未完成登记组计入计划分母。','样本来源和独立性按用户声明记录，不是由应用证实。','首次结果保留；重复运行不覆盖首次成绩。开发与未见测试分别导出并使用新会话，汇总不排除开发失败。','帧分析耗时不包含取帧/解码，也不是提醒端到端延迟。']};const json=JSON.stringify(report,null,2);$('report-json').value=json;$('report-preview').hidden=false;$('report-preview').open=true;if(reportUrl)URL.revokeObjectURL(reportUrl);reportUrl=URL.createObjectURL(new Blob([json],{type:'application/json'}));$('download-report').href=reportUrl;$('download-report').download=`clearpath-evaluation-${new Date().toISOString().slice(0,10)}.json`;notify('完整报告已生成，可下载或复制 JSON 保存。');});
